/*
 * Re-export all Speakeasy-generated SDK modules from the root so consumers can do:
 *   import { Flexprice, FlexPriceError, CreateCustomerRequest } from "@flexprice/sdk";
 * All models (shared, errors, operations, callbacks, webhooks) are re-exported from a single models index.
 * Customer Portal (custom) is also re-exported for dashboard aggregation.
 * Short-name aliases for generated enum/const types (Speakeasy uses long GithubCom... names).
 */
export * from "./sdk/models/index.js";
export {
  CustomerPortal,
  createCustomerPortal,
  getCustomerDashboardData,
  type DashboardOptions,
  type CustomerDashboardData,
} from "./sdk/customer-portal.js";

/**
 * FlexPrice Customer Portal - Dashboard API (custom)
 *
 * Merged from api/custom/typescript/. Uses the FlexPrice SDK
 * (customers, subscriptions, invoices, wallets, entitlements, features).
 */

import type { SDKOptions } from "../lib/config.js";
import { Flexprice } from "../index.js";
import type * as models from "./models/index.js";

/** Return type of {@link Flexprice.customers.getCustomerByExternalId} (typically {@link models.CustomerResponse}). */
type CustomerFromLookup = Awaited<
  ReturnType<Flexprice["customers"]["getCustomerByExternalId"]>
>;

export type DashboardOptions = {
  subscriptionLimit?: number;
  invoiceLimit?: number;
  includeCustomer?: boolean;
  includeSubscriptions?: boolean;
  includeInvoices?: boolean;
  includeUsage?: boolean;
  includeEntitlements?: boolean;
  includeSummary?: boolean;
  includeWalletBalance?: boolean;
};

export interface CustomerDashboardData {
  customer?: CustomerFromLookup;
  usage?: models.CustomerUsageSummaryResponse;
  entitlements?: models.CustomerEntitlementsResponse;
  walletBalance?: models.WalletResponse;
  activeSubscriptions?: models.SubscriptionResponse[];
  invoices?: models.InvoiceResponse[];
  summary?: models.CustomerMultiCurrencyInvoiceSummary;
  metadata: {
    fetchedAt: string;
    customerId: string;
    totalSubscriptions?: number;
    totalInvoices?: number;
    errors?: string[];
    warnings?: string[];
  };
}

function isRecord(x: unknown): x is Record<string, unknown> {
  return typeof x === "object" && x !== null;
}

/**
 * Customer Portal – single entry point for customer dashboard data using the FlexPrice SDK.
 */
export class CustomerPortal {
  private sdk: Flexprice;

  constructor(options: SDKOptions) {
    this.sdk = new Flexprice(options);
  }

  /**
   * Get dashboard data for a customer by external ID.
   */
  async getDashboardData(
    customerExternalId: string,
    options: DashboardOptions = {},
  ): Promise<CustomerDashboardData> {
    const opts = {
      subscriptionLimit: 10,
      invoiceLimit: 5,
      includeCustomer: true,
      includeSubscriptions: true,
      includeInvoices: true,
      includeUsage: true,
      includeEntitlements: true,
      includeSummary: true,
      includeWalletBalance: true,
      ...options,
    };

    const errors: string[] = [];
    const warnings: string[] = [];
    const now = new Date().toISOString();

    const safe = async <T>(label: string, fn: () => Promise<T>): Promise<T | undefined> => {
      try {
        return await fn();
      } catch (e) {
        const msg = `${label}: ${e instanceof Error ? e.message : String(e)}`;
        errors.push(msg);
        return undefined;
      }
    };

    const customer = await safe("Customer lookup", () =>
      this.sdk.customers.getCustomerByExternalId(customerExternalId),
    );

    const customerData =
      customer && isRecord(customer) && "id" in customer && customer["id"] ? customer : undefined;
    if (!customerData?.["id"]) {
      return {
        metadata: {
          fetchedAt: now,
          customerId: customerExternalId,
          ...(errors.length ? { errors } : { errors: [`Customer not found: ${customerExternalId}`] }),
        },
      };
    }

    const customerId = customerData["id"] as string;

    const [usage, entitlements, walletBalance, subsResp, invoicesResp, summary] = await Promise.all([
      opts.includeUsage
        ? safe("Usage", () =>
          this.sdk.customers.getCustomerUsageSummary({ customerId }),
        )
        : undefined,
      opts.includeEntitlements
        ? safe("Entitlements", () =>
          this.sdk.customers.getCustomerEntitlements(customerId),
        )
        : undefined,
      opts.includeWalletBalance
        ? safe("Wallets", () =>
          this.sdk.wallets.getCustomerWallets({
            id: customerId,
            includeRealTimeBalance: true,
          }),
        ).then((w) => (Array.isArray(w) && w.length > 0 ? w[0] : undefined))
        : undefined,
      opts.includeSubscriptions
        ? safe("Subscriptions", () =>
          this.sdk.subscriptions.querySubscription({
            customerId,
            externalCustomerId: customerExternalId,
            limit: opts.subscriptionLimit ?? 10,
          }),
        )
        : undefined,
      opts.includeInvoices
        ? safe("Invoices", () =>
          this.sdk.invoices.queryInvoice({
            customerId,
            limit: opts.invoiceLimit ?? 5,
          }),
        )
        : undefined,
      opts.includeSummary
        ? safe("Summary", () =>
          this.sdk.invoices.getCustomerInvoiceSummary(customerId),
        )
        : undefined,
    ]);

    const activeSubscriptions: models.SubscriptionResponse[] =
      subsResp && isRecord(subsResp) && "items" in subsResp && Array.isArray(subsResp["items"])
        ? subsResp["items"]
        : [];
    const invoices: models.InvoiceResponse[] =
      invoicesResp && isRecord(invoicesResp) && "items" in invoicesResp && Array.isArray(invoicesResp["items"])
        ? invoicesResp["items"]
        : [];

    const isSuccess = <T>(r: T): r is Exclude<T, { error?: unknown }> =>
      !r || typeof r !== "object" || r === null || !("error" in r);

    const metadata = {
      fetchedAt: now,
      customerId: customerExternalId,
      totalSubscriptions: activeSubscriptions.length,
      totalInvoices: invoices.length,
      ...(errors.length ? { errors } : {}),
      ...(warnings.length ? { warnings } : {}),
    };

    const result: CustomerDashboardData = { metadata };

    if (opts.includeCustomer && customerData) result.customer = customerData as CustomerFromLookup;
    if (usage && isSuccess(usage)) result.usage = usage;
    if (entitlements && isSuccess(entitlements)) result.entitlements = entitlements;
    if (walletBalance && isSuccess(walletBalance)) result.walletBalance = walletBalance;
    if (activeSubscriptions.length > 0) result.activeSubscriptions = activeSubscriptions;
    if (invoices.length > 0) result.invoices = invoices;
    if (summary && isSuccess(summary)) result.summary = summary;

    return result;
  }
}

export function createCustomerPortal(options: SDKOptions): CustomerPortal {
  return new CustomerPortal(options);
}

export async function getCustomerDashboardData(
  customerExternalId: string,
  options?: DashboardOptions,
  config?: SDKOptions,
): Promise<CustomerDashboardData> {
  if (!config) throw new Error("SDKOptions required (e.g. serverURL, apiKeyAuth)");
  const portal = new CustomerPortal(config);
  return portal.getDashboardData(customerExternalId, options ?? {});
}

# FlexPrice Go SDK

Type-safe Go client for the FlexPrice API: billing, metering, and subscription management for SaaS and usage-based products.

## Requirements

- **Go 1.20+** (Go modules required)

## Installation

```bash
go get github.com/flexprice/go-sdk/v2
```

Then in your code:

```go
import "github.com/flexprice/go-sdk/v2"
```

## Environment

| Variable | Required | Description |
| -------- | -------- | ----------- |
| `FLEXPRICE_API_KEY` | Yes | API key |
| `FLEXPRICE_API_HOST` | Optional | Full base URL including `https://` and `/v1` (default: `https://us.api.flexprice.io/v1`). No trailing slash. |

**Integration tests** in [api/tests/go/test_sdk.go](../tests/go/test_sdk.go) use a different env shape (host without scheme); see [api/tests/README.md](../tests/README.md).

## Quick start

Initialize the client, create a customer, ingest an event:

```go
package main

import (
	"context"
	"fmt"
	"log"
	"os"
	"time"

	"github.com/flexprice/go-sdk/v2"
	"github.com/flexprice/go-sdk/v2/models/types"
	"github.com/joho/godotenv"
)

func main() {
	godotenv.Load()

	apiKey := os.Getenv("FLEXPRICE_API_KEY")
	serverURL := os.Getenv("FLEXPRICE_API_HOST")
	if serverURL == "" {
		serverURL = "https://us.api.flexprice.io/v1"
	}
	if apiKey == "" {
		log.Fatal("Set FLEXPRICE_API_KEY in .env or environment")
	}

	client := flexprice.New(
		flexprice.WithServerURL(serverURL),
		flexprice.WithSecurity(apiKey),
	)
	ctx := context.Background()

	externalID := fmt.Sprintf("sample-customer-%d", time.Now().Unix())
	_, err := client.Customers.CreateCustomer(ctx, types.CreateCustomerRequest{
		ExternalID: externalID,
		Name:       flexprice.String("Sample Customer"),
		Email:      flexprice.String("sample@example.com"),
	})
	if err != nil {
		log.Fatalf("CreateCustomer: %v", err)
	}

	req := types.IngestEventRequest{
		EventName:          "Sample Event",
		ExternalCustomerID: externalID,
		Properties:         map[string]string{"source": "sample_app", "environment": "test"},
	}
	resp, err := client.Events.IngestEvent(ctx, req)
	if err != nil {
		log.Fatalf("IngestEvent: %v", err)
	}
	if resp != nil {
		meta := resp.GetHTTPMeta()
		if hr := meta.GetResponse(); hr != nil && hr.StatusCode == 202 {
			fmt.Println("Event created (202).")
		}
	}

	// List events: client.Events.ListRawEvents(ctx, ...)
	// See the API reference and the examples/ directory for more operations.
}
```

For more examples and all API operations, see the [API reference](https://docs.flexprice.io) and the [examples](examples/) in this repo.

## Optional fields and pointer helpers

Required fields are plain Go values; optional fields are pointers. The SDK ships helper functions so you never need a temporary variable:

```go
package main

import (
	"context"
	"fmt"
	"log"
	"os"
	"time"

	"github.com/flexprice/go-sdk/v2"
	"github.com/flexprice/go-sdk/v2/models/types"
)

func main() {
	apiKey := os.Getenv("FLEXPRICE_API_KEY")
	serverURL := os.Getenv("FLEXPRICE_API_HOST")
	if serverURL == "" {
		serverURL = "https://us.api.flexprice.io/v1"
	}
	if apiKey == "" {
		log.Fatal("Set FLEXPRICE_API_KEY in your environment")
	}

	client := flexprice.New(
		flexprice.WithServerURL(serverURL),
		flexprice.WithSecurity(apiKey),
	)
	ctx := context.Background()

	externalID := fmt.Sprintf("acme-%d", time.Now().UnixNano())
	resp, err := client.Customers.CreateCustomer(ctx, types.CreateCustomerRequest{
		ExternalID: externalID,
		Name:       flexprice.String("Acme Corp"),
		Email:      flexprice.String("billing@acme.com"),
		// Optional address fields
		AddressLine1:   flexprice.String("123 Main St"),
		AddressCity:    flexprice.String("San Francisco"),
		AddressState:   flexprice.String("CA"),
		AddressCountry: flexprice.String("US"),
		// Generic helper for any type
		Metadata: flexprice.Pointer(map[string]string{"plan_tier": "growth"}),
	})
	if err != nil {
		log.Fatalf("CreateCustomer: %v", err)
	}
	if resp != nil {
		fmt.Println("created customer")
	}
}
```

Available helpers: `flexprice.String`, `flexprice.Bool`, `flexprice.Int`, `flexprice.Int64`, `flexprice.Float32`, `flexprice.Float64`, `flexprice.Pointer[T]`.

## Nil-safe getters

Every generated type has nil-safe `Get*()` methods. Calling a getter on a nil receiver returns the zero value for that getter’s return type (for example `nil` pointers, empty strings where the getter returns `string`) — no panic:

```go
package main

import (
	"fmt"

	"github.com/flexprice/go-sdk/v2/models/dtos"
	"github.com/flexprice/go-sdk/v2/models/types"
)

func main() {
	var sub *types.Subscription // nil

	// Safe — returns nil *string instead of panicking
	fmt.Println("id on nil subscription:", sub.GetID())

	// Safe chain — returns nil instead of panicking
	fmt.Println("billing cycle on nil subscription:", sub.GetBillingCycle())

	// Prefer getters when traversing nested optional fields (e.g. after GetSubscription).
	// resp can be nil or point to a response with a nil Subscription field.
	var resp *dtos.GetSubscriptionResponse
	if s := resp.GetSubscription(); s != nil {
		fmt.Println(s.GetID(), s.GetStatus())
		if cycle := s.GetBillingCycle(); cycle != nil {
			fmt.Println(cycle.GetInterval())
		}
	}
}
```

## Error handling

Use `errors.As` for typed errors, or the `errorutils` helpers for HTTP status checks:

```go
package main

import (
	"context"
	"errors"
	"log"
	"os"

	"github.com/flexprice/go-sdk/v2"
	"github.com/flexprice/go-sdk/v2/errorutils"
	sdkerrors "github.com/flexprice/go-sdk/v2/models/errors"
	"github.com/flexprice/go-sdk/v2/models/types"
)

func main() {
	apiKey := os.Getenv("FLEXPRICE_API_KEY")
	serverURL := os.Getenv("FLEXPRICE_API_HOST")
	if serverURL == "" {
		serverURL = "https://us.api.flexprice.io/v1"
	}
	if apiKey == "" {
		log.Fatal("Set FLEXPRICE_API_KEY in your environment")
	}

	client := flexprice.New(
		flexprice.WithServerURL(serverURL),
		flexprice.WithSecurity(apiKey),
	)
	ctx := context.Background()

	req := types.CreateCustomerRequest{
		ExternalID: "acme-error-handling-example",
		Name:       flexprice.String("Acme Corp"),
	}

	resp, err := client.Customers.CreateCustomer(ctx, req)
	if err != nil {
		switch {
		case errorutils.IsConflict(err):
			// 409 — customer already exists
			log.Println("duplicate customer, continuing")
		case errorutils.IsValidation(err):
			// 400 — bad request
			var apiErr *sdkerrors.APIError
			errors.As(err, &apiErr)
			log.Fatalf("validation error: %s", apiErr.Body)
		case errorutils.IsNotFound(err):
			// 404
			log.Fatalf("not found")
		default:
			log.Fatalf("unexpected error: %v", err)
		}
	}
	if resp != nil {
		log.Println("CreateCustomer succeeded")
	}
}
```

Available helpers: `IsNotFound` (404), `IsValidation` (400), `IsConflict` (409), `IsRateLimit` (429), `IsPermissionDenied` (403), `IsServerError` (5xx).

## Async client (high-volume events)

For high-volume event ingestion, use the async client: it batches events and sends them in the background.

```go
package main

import (
	"log"
	"os"
	"time"

	"github.com/flexprice/go-sdk/v2"
)

func main() {
	apiKey := os.Getenv("FLEXPRICE_API_KEY")
	serverURL := os.Getenv("FLEXPRICE_API_HOST")
	if serverURL == "" {
		serverURL = "https://us.api.flexprice.io/v1"
	}
	if apiKey == "" {
		log.Fatal("Set FLEXPRICE_API_KEY in your environment")
	}

	client := flexprice.New(
		flexprice.WithServerURL(serverURL),
		flexprice.WithSecurity(apiKey),
	)

	asyncConfig := flexprice.DefaultAsyncConfig()
	asyncConfig.Debug = true
	asyncClient := client.NewAsyncClientWithConfig(asyncConfig)
	defer asyncClient.Close()

	// Simple event
	if err := asyncClient.Enqueue("api_request", "customer-123", map[string]interface{}{
		"path": "/api/resource", "method": "GET", "status": "200",
	}); err != nil {
		log.Fatalf("Enqueue: %v", err)
	}

	// Event with full options
	if err := asyncClient.EnqueueWithOptions(flexprice.EventOptions{
		EventName:          "file_upload",
		ExternalCustomerID: "customer-123",
		Properties:         map[string]interface{}{"file_size_bytes": 1048576},
		Source:             "upload_service",
		Timestamp:          time.Now().Format(time.RFC3339),
	}); err != nil {
		log.Fatalf("EnqueueWithOptions: %v", err)
	}
}
```

**Benefits:** Automatic batching, background sending, configurable batch size and flush interval, optional debug logging. Call `Close()` before exit to flush remaining events.

